// A MongoDB document — equivalent to a SQL row
// but with nested objects and arrays natively supported
{
  _id: ObjectId("507f1f77bcf86cd799439011"),  // auto-generated unique ID
  name: "Alice",
  age: 30,
  email: "alice@example.com",
  tags: ["admin", "user"],        // arrays natively supported
  address: {                      // nested objects (embedded documents)
    city: "Mumbai",
    state: "MH",
    zip: "400001"
  },
  createdAt: ISODate("2026-01-15T10:00:00Z")
}

// Another document in the SAME collection — different fields!
{
  _id: ObjectId("507f1f77bcf86cd799439012"),
  name: "Bob",
  age: 25,
  // No email, no address — that's perfectly valid in MongoDB
  preferences: { theme: "dark", language: "en" }
}

