// Try building a MongoDB-style document for a blog post
// What fields would you include?
const blogPost = {
  _id: 'post-001',       // custom _id (string)
  title: 'Getting Started with MongoDB',
  author: {
    name: 'Alice',
    email: 'alice@example.com'
  },
  tags: ['mongodb', 'nosql', 'tutorial'],
  published: true,
  views: 0,
  createdAt: new Date()
};

console.log('Blog post document:');
console.log(JSON.stringify(blogPost, null, 2));
console.log('\nFields:', Object.keys(blogPost));
